define("theme_echealth/drawer_layout", [], function() {
    "use strict";
    return {
        init: function() {
            if (!document.body.classList.contains('pagelayout-mydashboard')) {
                return;
            }
            var toggle = document.querySelector('#page .drawer-right-toggle');
            var actions = document.querySelector('#page-header .w-100 > .d-flex.flex-wrap > .ms-auto.d-flex');
            if (toggle && actions) {
                actions.classList.add('ec-dashboard-header-actions');
                actions.insertBefore(toggle, actions.firstChild);
            }
        }
    };
});
